import React, { useState } from 'react'
import { Check } from 'lucide-react'
import { useAuth } from '../../contexts/AuthContext'
import { supabase } from '../../lib/supabase'
import { invalidateVenueCache } from '../../services/venueService'

interface AttendanceButtonProps {
  venueId: string
  venueName: string
  isAttending?: boolean
  onAttendanceChange?: (isAttending: boolean) => void
}

export const AttendanceButton: React.FC<AttendanceButtonProps> = ({
  venueId,
  venueName,
  isAttending = false,
  onAttendanceChange
}) => {
  const { user, profile, loading } = useAuth()
  const [showRegistration, setShowRegistration] = useState(false)
  const [processingAttendance, setProcessingAttendance] = useState(false)

  // 参加表明処理
  const handleAttendance = async () => {
    if (!user) {
      // 未ログインの場合は登録フォームを表示
      setShowRegistration(true)
      return
    }

    setProcessingAttendance(true)
    try {
      if (isAttending) {
        // 参加取り消し
        if (supabase) {
          await supabase
            .from('venue_attendances')
            .delete()
            .eq('user_id', user.id)
            .eq('venue_id', venueId)
        }
        onAttendanceChange?.(false)
      } else {
        // 参加表明
        if (supabase) {
          await supabase
            .from('venue_attendances')
            .insert({
              user_id: user.id,
              venue_id: venueId,
              is_public: true
            })
        }
        onAttendanceChange?.(true)
      }
      
      // キャッシュを無効化
      invalidateVenueCache(venueId, user.id)
    } catch (error) {
      console.error('参加表明エラー:', error)
    } finally {
      setProcessingAttendance(false)
    }
  }

  if (loading) {
    return (
      <button disabled className="px-4 py-2 bg-gray-300 text-gray-500 rounded-lg">
        読み込み中...
      </button>
    )
  }

  return (
    <>
      <button
        onClick={handleAttendance}
        disabled={processingAttendance}
        className={`flex items-center gap-2 px-6 py-2 rounded-lg font-medium transition-colors ${
          isAttending
            ? 'bg-green-600 text-white hover:bg-green-700'
            : 'bg-gray-400 text-white hover:bg-gray-500'
        } disabled:opacity-50`}
      >
        {processingAttendance ? (
          '処理中...'
        ) : (
          <>
            <Check className="h-4 w-4" />
            <span>{isAttending ? '参加予定' : '参加未定'}</span>
          </>
        )}
      </button>

      {showRegistration && (
        <QuickRegistrationModal
          venueId={venueId}
          venueName={venueName}
          onClose={() => setShowRegistration(false)}
          onSuccess={() => {
            setShowRegistration(false)
            handleAttendance()
          }}
        />
      )}
    </>
  )
}

interface QuickRegistrationModalProps {
  venueId: string
  venueName: string
  onClose: () => void
  onSuccess: () => void
}

const QuickRegistrationModal: React.FC<QuickRegistrationModalProps> = ({
  venueId,
  venueName,
  onClose,
  onSuccess
}) => {
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    username: '',
    full_name: '',
    x_account_url: ''
  })
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!supabase) {
      onSuccess()
      return
    }

    setLoading(true)
    setError('')

    try {
      // 1. ユーザー登録
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email: formData.email,
        password: formData.password,
        options: {
          data: {
            username: formData.username,
            full_name: formData.full_name
          }
        }
      })

      if (authError) {
        throw authError
      }

      if (authData.user) {
        // 2. プロフィール情報を更新（X URLを含む）
        if (formData.x_account_url) {
          await supabase
            .from('profiles')
            .update({ x_account_url: formData.x_account_url })
            .eq('id', authData.user.id)
        }
      }

      onSuccess()
    } catch (err: any) {
      setError(err.message || '登録に失敗しました')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg p-6 max-w-md w-full mx-4 max-h-90vh overflow-y-auto">
        <h2 className="text-xl font-bold text-gray-900 mb-4">
          {venueName}への参加表明
        </h2>
        
        <p className="text-gray-600 mb-4 text-sm">
          参加表明するにはアカウント登録が必要です
        </p>

        {error && (
          <div className="mb-4 p-3 bg-red-50 text-red-700 rounded-lg text-sm">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              メールアドレス *
            </label>
            <input
              type="email"
              value={formData.email}
              onChange={(e) => setFormData({...formData, email: e.target.value})}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              パスワード *
            </label>
            <input
              type="password"
              value={formData.password}
              onChange={(e) => setFormData({...formData, password: e.target.value})}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
              minLength={6}
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              ユーザー名 *
            </label>
            <input
              type="text"
              value={formData.username}
              onChange={(e) => setFormData({...formData, username: e.target.value})}
              placeholder="bijigaku_fan"
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              表示名
            </label>
            <input
              type="text"
              value={formData.full_name}
              onChange={(e) => setFormData({...formData, full_name: e.target.value})}
              placeholder="美辞学ファン"
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              XアカウントURL（任意）
            </label>
            <input
              type="url"
              value={formData.x_account_url}
              onChange={(e) => setFormData({...formData, x_account_url: e.target.value})}
              placeholder="https://x.com/your_username"
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
            />
            <p className="text-xs text-gray-500 mt-1">
              設定すると参加者一覧でXアカウントへのリンクが表示されます
            </p>
          </div>
          
          <div className="flex space-x-3 pt-4">
            <button
              type="submit"
              disabled={loading}
              className="flex-1 px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 disabled:opacity-50"
            >
              {loading ? '登録中...' : '登録して参加表明'}
            </button>
            
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400"
            >
              キャンセル
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}